def run(args):
    cmd = [GOG, "--account", ACC, "--json"] + args
    r = subprocess.run(cmd, capture_output=True, encoding='utf-8')
    if r.returncode != 0:
        print(f"ERROR: {r.stderr.strip()[:200]}")
        return None
    try:
        return json.loads(r.stdout)
    except Exception as e:
        print(f"JSON Parse Error: {e}")
        return None

