for i, q in enumerate(questions):
    if 'section' in q:
        print(f"  -- Section header: {q['section']} --")
        continue
        
    title = q['en']
    qtype = "radio" if q['type'] == 'radio' else ("scale" if q['type'] == 'scale' else "text")
    
    args = ["forms", "add-question", "--title", title, "--type", qtype, form_id, "--required"]
    
    if q['type'] in ['radio', 'checkbox']:
        for en_opt, hi_opt in zip(q['opts_en'], q['opts_hi']):
            args += ["--option", f"{en_opt} / {hi_opt}"]
            
    elif q['type'] == 'scale':
        args += ["--scale-low", str(q['scale_low']), "--scale-high", str(q['scale_high'])]
        args += ["--scale-low-label", q['low_label'], "--scale-high-label", q['high_label']]
        
    r = run(args)
    status = "OK" if r else "FAIL"
    print(f"  [{i}] {status}: {title[:50]}...")
    time.sleep(1) # Prevent rate limiting

